	}

	if !a.IsEmptyCodeHash() {
		structLength += 33 // 32-byte array + 1 bytes for length
	}

	if a.Incarnation > 0 {
		structLength += uint(common.BitLenToByteLen(bits.Len64(a.Incarnation))) + 1
	}

